#!/bin/bash
# Pre-commit guard: block if working tree has untracked/unstaged files.
# Prevents accidental partial commits.
# Bypass: git -c devshop.dirtyTreeReason="<reason>" (human-only, not shown in output).
# Called from .hooks/pre-commit (generated by init-devshop.sh, invoked by husky).
set -euo pipefail

# Check for bypass (git -c flags are natively accessible in husky context)
BYPASS=$(git config --get devshop.dirtyTreeReason 2>/dev/null || true)
if [ -n "$BYPASS" ]; then
  echo "✓ Dirty tree acknowledged: $BYPASS"
  exit 0
fi

DIRTY=$(git status --porcelain 2>/dev/null | grep -E '^\?\?|^ [MD]' || true)
[ -z "$DIRTY" ] && exit 0

echo ""
echo "✖ Working tree not clean before commit. Untracked or unstaged files:"
echo "$DIRTY" | sed 's/^/    /'
echo ""
echo "  Address these before committing — stage, gitignore, or stash."
exit 1
